-- 다른 가수 공식 채널의 YouTube Shorts 목록에서 확인한 tripleS 협업 영상을 등록한다.
CREATE TEMPORARY TABLE tmp_artist_collaboration_shorts (
    youtube_id VARCHAR(32) NOT NULL PRIMARY KEY,
    channel_id VARCHAR(64) NOT NULL,
    title VARCHAR(255) NOT NULL,
    duration VARCHAR(32) NOT NULL,
    views BIGINT NOT NULL,
    published_on DATE NOT NULL,
    artist_names VARCHAR(240) NOT NULL,
    existing_media BOOLEAN NOT NULL DEFAULT FALSE
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


UPDATE tmp_artist_collaboration_shorts seed
JOIN media m ON BINARY LOWER(m.youtube_id) = BINARY LOWER(seed.youtube_id)
SET seed.existing_media = TRUE, m.tab = 'shorts', m.curated_external = TRUE;

SELECT youtube_id, channel_id, 'shorts', title, duration, views, published_on,
       YEAR(published_on) * 10000 + MONTH(published_on) * 100 + DAY(published_on), TRUE
FROM tmp_artist_collaboration_shorts
WHERE NOT existing_media;

SELECT DISTINCT m.id, a.artist_id
FROM tmp_artist_collaboration_shorts seed
JOIN media m ON BINARY m.youtube_id = BINARY seed.youtube_id
JOIN artist a ON FIND_IN_SET(BINARY a.name, BINARY seed.artist_names) > 0
WHERE NOT seed.existing_media;

DROP TEMPORARY TABLE tmp_artist_collaboration_shorts;
